import {signalDiagnostics,confusionRows,readiness,rankedMatches} from './insights.js';
import {STARTER_PHRASES} from './communication.js';
import {REST,UNKNOWN} from './core.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function studioView(profile,model,report={excluded:[],readyIds:[]}){
 if(!profile)return '<div class="page-heading"><h1>Signal analyzer</h1><p>Create a profile to explore what Relay learns.</p></div><button class="button" data-action="new-profile">Create a profile</button>';
 const checks=readiness(profile,model),diagnostics=signalDiagnostics(model),rows=confusionRows(profile);
 return '<div class="page-heading"><h1>Signal analyzer</h1><p class="muted">See the difference between a learned movement, an uncertain input, and an intentional selection.</p></div>'+
 '<section class="card saved-gesture-summary"><h2>'+profile.gestures.length+' saved gestures</h2><p>'+profile.rest.length+' resting samples · '+(report.readyIds?.length||0)+' gestures ready</p>'+(!model?'<p class="notice warn">'+esc(report.error||'Your recordings are saved, but the recognizer needs attention.')+'</p>':'')+(report.excluded?.length?'<ul>'+report.excluded.map(g=>'<li><b>'+esc(g.name)+'</b>: '+esc(g.reason)+'</li>').join('')+'</ul>':'')+'<button class="button secondary" data-action="nav-teach">Review saved gestures</button></section>'+'<div class="studio-grid"><section class="card live-decision"><div class="section-label" style="margin-top:0"><h3>Inside the recognizer</h3><span class="badge">LIVE · ON DEVICE</span></div><div id="live-insights"><div class="empty-state">Enable your camera to see the recognizer work.</div></div></section>'+
 '<section class="card milestones"><div class="eyebrow">PRACTICE MILESTONES</div><div class="milestone-total">'+checks.filter(c=>c.done).length+'<span> / 4</span></div>'+checks.map(c=>'<div class="milestone '+(c.done?'complete':'')+'"><span>'+(c.done?'✓':'○')+'</span><p>'+esc(c.label)+'</p></div>').join('')+'<p class="small-text muted">Milestones guide practice. They do not establish clinical reliability.</p></section></div>'+
 '<section class="card"><div class="section-label" style="margin-top:0"><h3>How distinct are your gestures?</h3><span>Training diagnostic</span></div><p class="small-text muted">Held poses are compared with rest and other gestures using the same body parts; movements use ordered recordings. Nearby signals may be confused. New attempts are the real test.</p>'+
 (diagnostics.length?'<div class="signal-cards">'+diagnostics.map(d=>'<article class="signal-card '+d.status+'"><div class="section-label" style="margin:0 0 15px"><strong>'+esc(d.label)+'</strong><span class="badge '+(d.status!=='separated'?'amber':'')+'">'+({overlap:'Potential overlap',close:'Close together',separated:'Separated examples',motion:'Recorded movement'}[d.status])+'</span></div><div class="separation-track"><span style="width:'+Math.min(100,d.ratio/3*100)+'%"></span></div><p class="small-text"><b>Closest to:</b> '+esc(d.nearest)+'<br>'+d.examples+' training examples · '+(d.kind==='motion'?'Temporal matching · test fresh attempts':d.ratio.toFixed(1)+'× acceptance-radius separation')+(d.channels?'<br>Uses '+esc(d.channels.join(' + ')):'')+'</p><button class="button small secondary" data-action="inspect-gesture" data-id="'+esc(d.id)+'">Review this gesture →</button></article>').join('')+'</div>':'<div class="empty-state">Your saved gestures are listed above. Resolve the recording issue to compare their signals.</div>')+'</section>'+
 '<section class="card"><div class="section-label" style="margin-top:0"><h3>What happened on fresh attempts?</h3><button class="button small secondary" data-action="export-report">Export evidence</button></div>'+
 (rows.some(r=>r.total)?'<div class="table-wrap"><table><thead><tr><th>Gesture</th><th>Correct</th><th>Missed</th><th>Wrong signal</th><th>Extra selections</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.name)+'</td><td class="result-pass">'+r.correct+' / '+r.total+'</td><td>'+r.missed+'</td><td>'+r.wrong+'</td><td>'+r.extra+'</td></tr>').join('')+'</tbody></table></div>':'<p class="small-text muted">No measured attempts yet. Start in Check accuracy. Rejected attempts remain in the denominator.</p>')+
 '<div class="button-row" style="margin-top:18px"><button class="button" data-action="nav-check">Measure new attempts →</button><button class="button secondary" data-action="nav-write">Write & speak</button></div></section>'+
 '<section class="local-architecture"><span>Camera</span><b>→</b><span>Visual features</span><b>→</b><span>Your examples</span><b>→</b><span>Intent gate</span><b>→</b><span>Your words</span></section>';
}
export function liveInsightHTML(model,vector,result,gate,latency,decision=result){
 if(!model)return '<div class="empty-state">Complete calibration to build your personal recognizer.</div>';
 const matches=rankedMatches(model,vector);
 // Recognition and permission to fire an action are separate: a held known pose
 // remains recognized even while the gate requires a return to rest.
 const matched=!!vector&&result.id!==REST&&result.id!==UNKNOWN;
 const label=result.label||model.entries?.find(e=>e.id===result.id)?.label||model.classes?.find(c=>c.id===result.id)?.label||'Recognized gesture';
 const state=!vector?'Tracking lost':result.id===REST?'Rest — no selection':!matched?'Uncertain — no selection':label;
 const reason=!vector?'Nothing will be selected until tracking and rest are recovered.':matched?(decision.reason||(gate.armed?'Hold to select.':'Return to rest before selecting again.')):result.reason||decision.reason||'A learned pose or completed movement is required before an action.';
 return '<div class="decision-state '+(vector&&result.id===UNKNOWN?'uncertain':'')+'"><span class="eyebrow">CURRENT GESTURE</span><strong>'+esc(state)+'</strong><p>'+esc(reason)+'</p></div>'+
 '<div class="match-list">'+(model.combined&&model.entries.some(e=>e.kind==='motion')?'<p class="small-text muted">Movement signals are matched over time. Pause at the endpoint, then return to the learned starting pose.</p>':'')+matches.map(m=>'<div class="match-row"><div><span>'+esc(m.label)+'</span><small>'+m.distance.toFixed(2)+' / '+m.limit.toFixed(2)+' limit</small></div><div class="match-track"><i style="width:'+Math.max(0,100*(1-m.distance/(m.limit*2)))+'%"></i></div></div>').join('')+'</div>'+
 '<div class="signal-pipeline"><span class="'+(vector?'lit':'')+'">1 · Tracking</span><span class="'+(matched?'lit':'')+'">2 · Match</span><span class="'+(gate.armed?'lit':'')+'">3 · Armed</span></div>'+
 '<p class="small-text muted" style="margin:14px 0 0">'+Math.round(latency||0)+' ms vision frame · Distances are not confidence probabilities.</p>';
}
export function vocabularyView(profile){
 if(!profile)return '';
 return '<form id="vocabulary-form" class="card"><div class="section-label" style="margin-top:0"><h3>My vocabulary</h3><span>PRIVATE · ON THIS DEVICE</span></div><p class="small-text muted">Save words and phrases you use often. Phrases are inserted into the message before you choose Speak.</p><label class="field">My phrases<textarea aria-label="My phrases" aria-describedby="phrase-help" name="phrases" rows="6" maxlength="7500">'+esc((profile.phrases||STARTER_PHRASES).join('\n'))+'</textarea><small id="phrase-help">One phrase per line. Up to 24 phrases, 300 characters each. The starter phrases are editable.</small></label><label class="field">Personal words<input aria-label="Personal words" aria-describedby="words-help" name="words" maxlength="2500" placeholder="Names, places, favorite words" value="'+esc((profile.words||[]).join(', '))+'"><small id="words-help">Separate words with commas. These appear first in local word completion.</small></label><label class="toggle"><input type="checkbox" name="completions" '+(profile.settings.completions!==false?'checked':'')+'> Offer word completions as I spell</label><button class="button secondary" type="submit">Save my vocabulary</button></form>';
}

